  'cdef.defaultModel': 'Modèle par défaut',
  'cdef.cliDefault': 'Défaut de Claude Code',
  'cdef.defaultModelHint': 'Les sessions affichent le modèle qui a réellement répondu à chaque tour.',
  'cdef.autoCompact': 'Compaction automatique',
  'cdef.autoCompactHint': 'Quand un tour se termine avec plus de contexte que ce seuil, Harness résume la session et continue dans un nouveau fil qui part de ce résumé (comme Compacter) : les longues sessions ne renvoient plus tout leur historique, ce qui économise des tokens. L’historique reste affiché.',
  'cdef.autoCompactOff': 'Désactivée',
  'cdef.autoCompactRecommended': 'recommandé',
  'cdef.idleCompact': 'Compacter au retour',
  'cdef.idleCompactHint': 'Le cache de prompt de Claude dure quelques minutes (une heure au plus). Quand vous écrivez dans une session inactive depuis plus longtemps, avec au moins ce contexte, Harness la résume d\'abord et votre message part dans un nouveau fil qui reprend ce résumé : l\'historique serait de toute façon renvoyé au prix fort, les tours suivants coûtent donc beaucoup moins. Coût : un tour de résumé (une courte attente) avant la réponse.',
  'cdef.smartResume': 'Reprise intelligente',
  'cdef.smartResumeHint': "Quand vous revenez sur une session dont le cache a expiré (voir ci-dessus) avec au moins ce contexte, ou après 5 minutes ou plus avec le double, Harness fait d'abord résumer la session par Claude pour le message que vous venez d'envoyer : le résumé garde exactement ce dont votre message a besoin (fichiers, commandes, valeurs, plan en cours), puis votre message part dans un fil neuf, bien plus léger. Mesuré sur de vraies reprises : 38 à 67 % de tokens en moins dès 100k, et des détails mieux gardés qu'avec le résumé simple. Désactivé = la règle ci-dessus seule.",
  'cdef.protectSecrets': 'Protéger les secrets',
  'cdef.protectSecretsHint': 'Les outils de Claude refusent de lire ou modifier les secrets du serveur (secrets.json) et les clés SSH (~/.ssh), quel que soit le mode de permissions. Cela empêche une instruction cachée dans une page web ou un e-mail de simplement les lire ; un script écrit pour ouvrir le fichier n’est pas bloqué - pour du contenu venu de l’extérieur, préférez un mode plus strict sur ce topic.',
  'cdef.shortTitles': 'Titres de session courts',
  'cdef.shortTitlesHint': 'Une nouvelle session est nommée en quelques mots d’après son premier message (sans les « bonjour » ni « tu peux… »). Désactivé : le titre est le début du message. Renommer une session l’emporte toujours.',
  'cdef.shortTitlesModel': 'Titres écrits par Claude',
  'cdef.shortTitlesModelHint': 'Le plus petit modèle nomme le sujet (titres plus justes). Un appel rapide par nouvelle session, compté dans votre forfait Claude.',
  'cdef.autoUpdate': 'Mettre à jour Claude Code automatiquement',
  'cdef.autoUpdateHint': 'Désactivé par défaut. Activé : quand une version stable plus récente de Claude Code sort (déjà utilisée depuis quelques jours, pas la toute dernière), le serveur l’installe dès que rien n’a tourné depuis 10 minutes (aucun tour, aucun message en attente, aucune tâche planifiée), et revient à la précédente si elle ne démarre pas. Vérifié toutes les 6 heures ; le résultat apparaît dans les notifications.',
  'cdef.autoUpdateLast': 'Dernière mise à jour : {from} → {to}, {date}',
  'cdef.autoUpdateFailed': 'Échec de la mise à jour vers {to} ({date})',
  'claude.permissionMode': 'Mode de permissions',
  'claude.mode.bypass': 'Accès complet (permissions contournées)',
  'claude.mode.bypassDesc': 'Claude exécute n’importe quelle commande et modifie n’importe quel fichier sans demander, avec les droits de l’utilisateur du service (root). À choisir uniquement si ce serveur est dédié à Claude.',
  'claude.mode.recommendedVps': 'VPS dédié uniquement',
  'claude.mode.acceptEdits': 'Accepter les modifications de fichiers',
  'claude.mode.acceptEditsDesc': 'Claude peut lire et écrire des fichiers ; les autres outils soumis à approbation (la plupart des commandes shell) sont refusés.',
  'claude.mode.default': 'Strict (refuser)',
  'claude.mode.defaultDesc': 'Tout outil soumis à approbation est refusé sans rien demander. Le plus sûr, mais Claude peut faire beaucoup moins.',
  'claude.mode.ask': 'Me demander',
  'claude.mode.askDesc': 'La lecture est libre ; le reste attend votre accord (Autoriser ou Refuser) dans la session, les notifications ou Telegram. Refusé au bout de 30 min sans réponse.',
  'claude.mode.note': 'Sauf en « Me demander », personne n’est sollicité : tout ce que le mode n’autorise pas est simplement refusé.',

