  'infra.mail.p.dmarc_inherited_sp_quarantine': 'Pas de DMARC sur {domain} : {parent} fixe p={parent_policy} mais sp={policy} pour ses sous-domaines, donc {domain} reçoit p={policy}.',
  'infra.mail.f.dmarc_inherited_sp_quarantine': 'Pour donner aussi p={parent_policy} à {domain}, remplacez sp={policy} par sp={parent_policy} (ou retirez sp=) dans l\'enregistrement de {parent}, ou donnez à {domain} son propre enregistrement _dmarc.{domain} avec p={parent_policy}. Ne baissez pas le p= de {parent}.',
  'infra.mail.p.dmarc_parent_invalid': 'Pas de DMARC sur {domain}, et celui de {parent} est invalide ({reason}) : aucune politique DMARC ne s\'applique à {domain}.',
