  'infra.mail.p.no_spf_unknown': 'Aucun enregistrement SPF : n\'importe qui peut prétendre envoyer du courrier en @{domain}.',
  'infra.mail.f.no_spf_unknown': 'Ajoutez sur {domain} un enregistrement TXT qui nomme chaque service par lequel vous envoyez du courrier. D\'après ses seuls MX, ce serait {record} : ajoutez l\'include: du service par lequel vous envoyez (votre fournisseur l\'indique) avant ~all, sinon le courrier que vous envoyez échoue au SPF.',

