  'settings.voice.desc': 'Parler au lieu de taper : transcription pour le bouton micro et les messages vocaux Telegram.',
  'voice.engine': 'Moteur de transcription',
  'voice.engineDesc': 'Harness ne peut pas écouter l\'audio : vos enregistrements sont d\'abord transformés en texte sur ce serveur. Harness lit la transcription.',
  'voice.engine.local': 'Sur ce serveur',
  'voice.engine.local.desc': 'Whisper tourne sur votre VPS. Privé et gratuit, sans clé. Plus lent sur les petits serveurs (sur 2 vCPU, une note d\'1 minute prend ~15 s avec « base », ~40 s avec « small ») et utilise ~0,5-1 Go de RAM pendant l\'usage.',
  'voice.engine.groq': 'Groq',
  'voice.engine.groq.desc': 'Whisper large v3 turbo dans le cloud : le plus rapide et le plus précis, très bon marché (environ 0,04 $ par heure d\'audio). Nécessite une clé API Groq.',
  'voice.engine.openai': 'OpenAI',
  'voice.engine.openai.desc': 'gpt-4o-mini-transcribe : précis, environ 0,18 $ par heure d\'audio. Nécessite une clé API OpenAI.',
